create or replace function public.business_growth_optimization_history(p_business_id uuid,p_limit integer default 50) returns jsonb language plpgsql stable security definer set search_path to 'public','auth','extensions','pg_catalog' as $function$ declare v_limit integer:=least(greatest(coalesce(p_limit,50),1),200); begin if auth.uid() is null then raise exception 'Authentication required'; end if; if not public.business_can_manage(p_business_id) then raise exception 'Business management access required'; end if; return jsonb_build_object('business_id',p_business_id,'actions',coalesce((select jsonb_agg(to_jsonb(x) order by x.updated_at desc) from (select id,location_id,surface,signal_type,action_type,status,created_at,updated_at,metadata->>'asset_type' asset_type,metadata->>'asset_id' asset_id,metadata->>'asset_title' asset_title,metadata->>'management_action' management_action,metadata->'measured_outcomes' measured_outcomes,metadata->'asset_result' asset_result from public.intelligence_action_links where business_id=p_business_id and surface='business_growth_cockpit' order by updated_at desc limit v_limit) x),'[]'::jsonb),'generated_at',now()); end $function$; revoke all on function public.business_growth_optimization_history(uuid,integer) from public,anon; grant execute on function public.business_growth_optimization_history(uuid,integer) to authenticated;
